args.command:
node --input-type=module - <<'EOF'
import { permit } from './limit.mjs';
const cases=[[-1,false],[0,true],[3,true],[4,false],['3',false],[null,false],[NaN,false],[2.5,false]];
let ok=true;
for (const [input, expected] of cases) {
  const got=permit(input);
  console.log(`${String(input)} => ${got} (expected ${expected})`);
  if (got!==expected) ok=false;
}
process.exit(ok?0:1);
EOF
